"""Rules for C1 (training data), C3 (model lifecycle), C4 (infrastructure), C6 (supply chain)."""
from .base import E, V, S, CODE_ONLY, CONFIG_ONLY, CODE_AND_CONFIG

ARTIFACT_EXT = r"(?:pt|pth|bin|safetensors|gguf|ggml|onnx|ckpt|pkl|pickle|h5|keras|tflite|joblib)"

RULES = [
    # ------------------------------------------------------------------ C4.1 / C6.1 unsafe deserialization
    V("AIS-DESER-001", "Unsafe pickle-based deserialization of model/data artifact", "4.1.2 6.1.1", S.HIGH,
      callee=r"\b(?:pickle|cPickle|_pickle|dill|cloudpickle)\.loads?\b|\bjoblib\.load\b|\bpd\.read_pickle\b|\bpandas\.read_pickle\b|\bshelve\.open\b",
      forbid=r"[\s\S]", langs=frozenset({"python", "notebook"}),
      message="Pickle-family deserialization can execute arbitrary code embedded in the artifact",
      remediation="Use a non-executable format (safetensors, ONNX, GGUF) or verify provenance + scan the artifact before loading; never unpickle untrusted data.",
      confidence="medium"),
    V("AIS-DESER-002", "torch.load without weights_only=True", "4.1.2 6.1.1", S.HIGH,
      callee=r"\btorch\.load\b", missing_any=r"weights_only\s*=\s*True", langs=frozenset({"python", "notebook"}),
      message="torch.load unpickles by default and can execute attacker-controlled code",
      remediation="Pass weights_only=True (or load .safetensors) and restrict the allow-listed globals."),
    V("AIS-DESER-003", "trust_remote_code=True executes code shipped with a model", "4.1.2 6.1.1 6.1.2", S.HIGH,
      pattern=r"trust_remote_code\s*[=:]\s*(?:True|true)",
      message="Model repositories can ship arbitrary Python executed on load",
      remediation="Set trust_remote_code=False, or pin a reviewed commit SHA (revision=...) from an approved source."),
    V("AIS-DESER-004", "numpy.load with allow_pickle=True", "4.1.2", S.HIGH,
      pattern=r"allow_pickle\s*=\s*True", langs=frozenset({"python", "notebook"}),
      message="allow_pickle=True re-enables arbitrary code execution through np.load",
      remediation="Leave allow_pickle=False and store arrays in .npy/.npz/safetensors."),
    V("AIS-DESER-005", "Keras safe_mode disabled / unsafe deserialization enabled", "4.1.2 6.1.1", S.HIGH,
      pattern=r"safe_mode\s*=\s*False|enable_unsafe_deserialization\s*\(|allow_dangerous_deserialization\s*=\s*True",
      message="Disabling Keras safe mode allows Lambda-layer code execution during model load",
      remediation="Keep safe_mode=True and avoid Lambda layers in distributed models."),
    V("AIS-DESER-006", "Unsafe YAML/marshal loading", "4.1.2", S.MEDIUM,
      callee=r"\byaml\.(?:load|unsafe_load|full_load)\b|\bmarshal\.loads?\b",
      missing_any=r"SafeLoader|CSafeLoader|BaseLoader", langs=frozenset({"python", "notebook"}),
      unless_line=r"safe_load", confidence="low",
      message="Non-safe YAML/marshal loaders can instantiate arbitrary objects",
      remediation="Use yaml.safe_load for model/config files."),

    # ------------------------------------------------------------------ C6.1 sources / integrity
    V("AIS-SUPPLY-001", "Model/dataset download without revision pinning", "6.1.2 6.1.3", S.LOW,
      callee=r"\b(?:\w+\.)?(?:from_pretrained|hf_hub_download|snapshot_download|load_dataset|SentenceTransformer|pipeline)\b",
      missing_any=r"revision\s*=|commit_hash|local_files_only|cache_dir\s*=\s*['\"]?/|\bos\.path|\bPath\(",
      langs=frozenset({"python", "notebook"}), confidence="low", max_hits_per_file=3,
      unless_line=r"AutoTokenizer|local|\.\/|\"\.|'\.|tokenizer|^\s*def |\bclass ",
      message="Hub artifacts resolved by branch name are mutable; a compromised/updated upstream is silently pulled",
      remediation="Pin `revision=<commit-sha>` for every third-party model/dataset and verify its hash."),
    V("AIS-SUPPLY-002", "Model artifact fetched over plaintext HTTP", "6.1.2 6.1.3", S.HIGH,
      pattern=r"http://(?!localhost|127\.0\.0\.1|0\.0\.0\.0|\[::1\]|host\.docker\.internal)[^\s\"'<>]+\." + ARTIFACT_EXT + r"\b",
      message="Plaintext download of model weights is trivially tamperable",
      remediation="Use HTTPS from an approved source and verify a pinned SHA-256 digest/signature."),
    V("AIS-SUPPLY-003", "Model download without checksum/signature verification", "6.1.3 3.1.3", S.MEDIUM,
      pattern=r"\b(?:curl|wget)\b[^\n|;]*\." + ARTIFACT_EXT + r"\b|\bADD\s+https?://\S+\." + ARTIFACT_EXT + r"\b",
      unless_file=r"sha256sum|shasum|sha512sum|--checksum|md5sum|cosign|sigstore|gpg\s+--verify|openssl\s+dgst|--hash",
      langs=frozenset({"dockerfile", "shell", "yaml", "text", "config"}), confidence="medium",
      message="Weights are downloaded with no integrity verification step in the same script",
      remediation="Verify a pinned SHA-256 (or a Sigstore/GPG signature) immediately after download and fail the build on mismatch."),
    V("AIS-SUPPLY-004", "Untrusted package index / trusted-host override", "6.1.2", S.MEDIUM,
      pattern=r"--trusted-host\b|--extra-index-url\b|--index-url\s+http://|pip\s+install[^\n]*\bgit\+http://",
      langs=frozenset({"requirements", "dockerfile", "shell", "yaml", "text", "toml", "config"}),
      message="Dependency confusion / MITM exposure for AI packages and models",
      remediation="Use a single approved index over HTTPS with hash pinning (--require-hashes)."),
    V("AIS-SUPPLY-005", "Curl-pipe-shell installation", "6.1.2 10.1.1", S.MEDIUM,
      pattern=r"\b(?:curl|wget)\b[^\n]*\|\s*(?:sudo\s+)?(?:ba|z)?sh\b",
      langs=frozenset({"dockerfile", "shell", "yaml", "text", "config"}),
      message="Remote script executed without verification",
      remediation="Download, verify checksum/signature, then execute — or install from a pinned package."),
    V("AIS-SUPPLY-006", "Unpinned moving model alias", "3.2.3", S.LOW,
      pattern=r"\bmodel(?:_name|_id|Id)?\s*[=:]\s*[\"'](?:gpt-4o|gpt-4|gpt-4-turbo|gpt-4\.1(?:-mini)?|gpt-5(?:-mini)?|gpt-3\.5-turbo|chatgpt-4o-latest|o1|o3|o3-mini|o4-mini|[\w.:/-]*-latest|[\w.:/-]*:latest|gemini-[\w.]+-(?:pro|flash)|claude-(?:3|3-5|3-7)-[\w-]+)[\"']",
      langs=frozenset(CODE_ONLY | {"yaml", "json", "toml", "config"}), confidence="low", max_hits_per_file=3,
      message="A floating model alias lets the provider change behaviour without triggering security re-evaluation",
      remediation="Pin dated/versioned model identifiers and gate alias bumps behind your evaluation suite."),

    # ------------------------------------------------------------------ Evidence: supply chain / lifecycle
    E("AIS-EV-MODELSCAN", "Model scanner for malicious code", "6.1.1",
      pattern=r"\b(?:modelscan|picklescan|fickling|protectai|model-scan|modelaudit|guardian-scan|hidden-layer|hiddenlayer|jfrog.*xray.*model)\b"),
    E("AIS-EV-SAFEFORMAT", "Safe serialization format / allow-list enforced", "4.1.2",
      pattern=r"weights_only\s*=\s*True|use_safetensors\s*=\s*True|\bsafetensors\b|trust_remote_code\s*=\s*False|ALLOWED_(?:MODEL_)?(?:EXTENSIONS|FORMATS|SUFFIXES)|allowed_(?:model_)?(?:extensions|formats|suffixes)|\.gguf\b"),
    E("AIS-EV-HASHVERIFY", "Artifact hash/checksum verification", "6.1.3 1.1.3 3.1.3 3.5.1 3.5.3 4.3.2",
      pattern=r"hashlib\.(?:sha256|sha512|sha3_256|blake2b)|sha256sum|sha512sum|shasum\s+-a|--checksum\b|expected[_ ]?(?:hash|sha256|checksum|digest)|verify[_ ]?(?:hash|checksum|digest|integrity)|--hash=sha(?:256|512)|\bdvc\.lock\b|revision\s*=\s*[\"'][0-9a-f]{40}[\"']|createHash\([\"']sha(?:256|512)[\"']\)|sha256\s*[:=]\s*[\"'][0-9a-f]{64}",
      confidence="low"),
    E("AIS-EV-SIGNING", "Cryptographic signing/verification of artifacts", "3.1.2 3.1.3 4.3.2",
      pattern=r"\bcosign\b|\bsigstore\b|model[_-]signing|\brekor\b|\bin-toto\b|\bslsa\b|\bminisign\b|gpg\s+--(?:verify|detach-sign)|\bnotation\s+(?:sign|verify)\b|openssl\s+dgst\s+-sign|\bapksigner\b|\bcodesign\b"),
    E("AIS-EV-BOMSIGN", "Signed AI-BOM / SBOM attestation", "6.2.2",
      pattern=r"cosign\s+(?:attest|sign-blob)|(?:sbom|bom)[^\n]{0,60}(?:sign|attest)|(?:sign|attest)[^\n]{0,60}(?:sbom|bom)\b|\bsyft\b[^\n]*attest|slsa-github-generator"),
    E("AIS-EV-AIBOM", "AI-BOM / ML-BOM tooling referenced", "6.2.1",
      pattern=r"\bcyclonedx\b|\bML-?BOM\b|\bAI-?BOM\b|\baibom\b|machine-learning-model|\bSPDX[-\s]?3\b|\bmodel[_ ]card\b|\bmodelcard\b|\bcdx\.json\b"),
    E("AIS-EV-BOMCHECK", "AI-BOM completeness gate", "6.2.3",
      pattern=r"(?:bom|aibom)[^\n]{0,80}(?:validate|complete|schema|fail)|cyclonedx[\w-]*\s+validate|--fail-on[-_]missing",
      confidence="low"),
    E("AIS-EV-REGISTRY", "Model registry / versioned artifact store", "3.1.1",
      pattern=r"\bmlflow\b|\bModelRegistry\b|model[_ -]registry|register_model|registered_model|wandb\.(?:log_artifact|Artifact)|ModelPackageGroup|\baiplatform\.Model\b|vertexai\.[\w.]*Model\.upload|ml_client\.models|push_to_hub|\bbentoml\.(?:models|\w+\.save_model)|\bclearml\b|\bkserve\b|\bseldon\b|Unity Catalog|\bneptune\b|\bcomet_ml\b|\bdvc\b"),
    E("AIS-EV-CHECKPOINT-REG", "Checkpoints registered as artifacts", "3.5.4",
      pattern=r"log_artifact\([^)]*checkpoint|register[^\n]{0,40}checkpoint|checkpoint[^\n]{0,40}(?:register|artifact)|save_total_limit|push_to_hub_strategy|hub_strategy",
      confidence="low"),
    E("AIS-EV-EVALTOOL", "Automated model safety/security evaluation tooling", "3.2.1 3.2.2 6.1.4 11.1.2 11.1.3",
      pattern=r"\bpromptfoo\b|\bgarak\b|\bdeepeval\b|\bragas\b|\binspect_ai\b|\blm[-_]eval\b|\blm_eval\b|\blighteval\b|openai/evals|\bpyrit\b|\bgiskard\b|\btrulens\b|\bharmbench\b|safety[_-]eval|alignment[_-]test|\bredteam\b|red_team|eval_suite|test_safety|\btoxigen\b|realtoxicityprompts|truthfulqa|do-not-answer|\bagentdojo\b|\bdeepteam\b|jailbreakbench|\bdecodingtrust\b|\bhelm\b.*(?:eval|benchmark)"),
    E("AIS-EV-EVAL-CI", "Safety evaluation wired into CI/CD", "3.2.1 6.1.4 11.1.2 11.1.5",
      pattern=r"promptfoo|garak|deepeval|ragas|inspect[_ ]eval|lm[-_]eval|pyrit|giskard|harmbench|safety[_-]eval|alignment[_-]test|redteam|red_team|eval_suite|pytest[^\n]*(?:safety|eval|redteam)",
      path_globs=(".github/workflows/*", ".gitlab-ci.yml", "Jenkinsfile", "azure-pipelines.yml", ".circleci/config.yml", "bitbucket-pipelines.yml", "*.gitlab-ci.yml", "cloudbuild.yaml", "buildspec.yml")),
    E("AIS-EV-MODELPIN", "Dated/versioned model identifiers", "3.2.3",
      pattern=r"\b(?:gpt-[\w.]+|claude-[\w.-]+|gemini-[\w.-]+|mistral-[\w.-]+)-(?:\d{4}-\d{2}-\d{2}|\d{8}|\d{3})\b", confidence="low"),
    E("AIS-EV-ROLLOUT", "Progressive rollout / automated rollback", "3.3.1",
      pattern=r"kind:\s*Rollout|argoproj\.io|\bflagger\b|\bcanary\b|RollingUpdate|blue[-_ ]green|progressive[_ ]delivery|AnalysisTemplate|automatedRollback|auto[_-]?rollback|rollbackOnFailure|rollback[_-]on[_-]failure|helm[^\n]*--atomic|AutoRollbackConfiguration|deployment_circuit_breaker|rollback_configuration|canaryTrafficPercent|BlueGreenUpdatePolicy|traffic_split|TrafficSplit",
      confidence="medium"),
    E("AIS-EV-ROLLBACK", "Full-state rollback mechanism", "3.3.2",
      pattern=r"kubectl\s+rollout\s+undo|helm\s+rollback|rollbackOnFailure|AutoRollbackConfiguration|rollback_configuration|rollback[_ ]to[_ ]version|restore[_ ]model[_ ]state|model[_ ]rollback|revisionHistoryLimit",
      confidence="low"),
    E("AIS-EV-REWARDHACK", "Reward-hacking / reward over-optimization controls", "3.5.2",
      pattern=r"reward[_ ]hacking|over-?optimi[sz]ation|kl_coef|init_kl_coef|target_kl|kl_penalty|adaptive_kl|gold_reward", confidence="low"),
    E("AIS-EV-TRAIN-ISOLATION", "Separate training/production environments", "3.4.2 3.4.1",
      pattern=r"namespace:\s*(?:training|ml-training|finetun\w*|train)|environment[_ ]separation|separate[_ ](?:vpc|account|project)\s+for\s+train", confidence="low"),

    # ------------------------------------------------------------------ C4 infra evidence
    E("AIS-EV-SANDBOX", "Sandbox / isolation technology for AI workloads", "4.1.1 9.3.1 10.1.3",
      pattern=r"\b(?:e2b|gvisor|runsc|firecracker|kata-containers|nsjail|firejail|bubblewrap|bwrap|seccomp|landlock|RestrictedPython|pyodide|wasmtime|wasmer|isolated-vm|DockerCommandLineCodeExecutor|apparmor|runtimeClassName|daytona|modal\.Sandbox|CodeInterpreterSandbox|SandboxedEnvironment|vm2)\b|\bsecurityContext\b|--cap-drop|--read-only|no-new-privileges"),
    E("AIS-EV-ATTEST", "Workload / GPU attestation", "4.1.3 4.2.3",
      pattern=r"\bnvtrust\b|\bNRAS\b|nvidia[_-]attestation|gpu[_ ]attestation|Azure Attestation|remote[_ ]attestation|workload[_ ]attestation|\bSEV-SNP\b|Intel\s+TDX|confidential[_ -]?containers", confidence="medium"),
    E("AIS-EV-CONFIDENTIAL", "Confidential computing / TEE", "4.1.4 4.2.2",
      pattern=r"confidential[_ -]?(?:computing|vm|containers|gpu|inference|space)|Trusted Execution|\bSGX\b|\bgramine\b|\boclum\b|nitro[_ -]enclaves?|\benclave\b|ConfidentialVM|\bTDX\b|\bSEV-SNP\b|\bnvtrust\b", confidence="medium"),
    E("AIS-EV-GPU-ISOLATION", "GPU partitioning / memory isolation", "4.2.4",
      pattern=r"nvidia\.com/mig|mig-parted|MIG[_ ]?(?:enabled|profile|strategy)|nvidia-smi\s+mig|mig\.strategy|nvidia-cuda-mps|--mig\b", confidence="medium"),
    E("AIS-EV-EDGE-AUTH", "Edge device strong authentication", "4.3.1",
      requires=("edge",),
      pattern=r"\bmTLS\b|mutual[_ ]tls|client[_ ]cert|device[_ ]cert|X\.509|AWS IoT|IoT Core|Azure IoT|device[_ ]attestation|\bTPM\b|\bSPIFFE\b|secure[_ ]element|device[_ ]identity"),
    E("AIS-EV-EDGE-ISOLATION", "On-device runtime isolation", "4.3.3",
      requires=("edge",),
      pattern=r"\bseccomp\b|AppSandbox|com\.apple\.security\.app-sandbox|isolatedProcess|\bSELinux\b|\bAppArmor\b|hardened[_ ]runtime", confidence="low"),
    E("AIS-EV-EDGE-CRYPTO", "Hardware-backed key store / secure enclave for on-device models", "4.3.4 4.3.5",
      requires=("edge",),
      pattern=r"AndroidKeyStore|\bKeychain\b|SecureEnclave|kSecAttrTokenIDSecureEnclave|EncryptedFile|SQLCipher|StrongBox|Secure Enclave|CryptoKit|AES\.GCM|ChaChaPoly|EncryptedSharedPreferences|android\.security\.keystore|TrustZone|OP-TEE"),

    # ------------------------------------------------------------------ C1 training data
    E("AIS-EV-DATA-INVENTORY", "Dataset inventory / datasheets / cards", "1.1.2",
      pattern=r"\bdatasheet\b|data[_ -]?card|dataset[_ -]card|DATA_CARD|\bcroissant\b|dataset_info|data[_ ]catalog|\bdatahub\b|data_sources?\b[:=]|source[_ ]inventory",
      requires=("training",), confidence="low"),
    E("AIS-EV-LINEAGE", "Dataset lineage / provenance tracking", "12.5.1 1.1.2",
      pattern=r"\bopenlineage\b|\bmarquez\b|\blineage\b|\bprovenance\b|mlflow\.log_input|mlflow\.data|\bdvc\.(?:yaml|lock)\b|\blakefs\b|\bpachyderm\b|\bprov-o\b",
      requires=("training",)),
    E("AIS-EV-DATA-MONITOR", "Training-data integrity / quality monitoring", "1.1.4",
      pattern=r"great_expectations|\bpandera\b|\bdeepchecks\b|\bevidently\b|\bwhylogs\b|tensorflow_data_validation|\btfdv\b|\bsoda\b|object_lock|ObjectLock|versioning\s*[{:=]\s*(?:true|\{)|\bdvc\s+status\b",
      requires=("training",)),
    E("AIS-EV-POISON", "Data poisoning detection", "1.3.1 1.3.5",
      pattern=r"\bcleanlab\b|activation[_ ]clustering|spectral[_ ]signature|poison\w*[_ ]detect|detect[_ ]poison|art\.defences\.detector|data[_ ]sanitization|neural[_ ]cleanse|anti-?backdoor|influence[_ ]function|clean[_ -]?label|feature[_ ]collision|sleeper[_ ]agent",
      requires=("training",)),
    E("AIS-EV-LABELQ", "Label quality / confidence checks", "1.3.2",
      pattern=r"\bcleanlab\b|find_label_issues|confident[_ ]learning|label[_ ]confidence|pseudo[_ -]?label[^\n]{0,80}threshold|label[_ ]noise|\bsnorkel\b|weak[_ ]supervision|annotator[_ ]agreement|cohen_kappa|inter[_ -]annotator",
      requires=("training",), confidence="low"),
    E("AIS-EV-BIAS", "Bias / fairness evaluation", "1.3.3",
      pattern=r"\bfairlearn\b|\baif360\b|\baequitas\b|bias[_ ]?(?:audit|eval|metric|test)|demographic[_ ]parity|equalized[_ ]odds|disparate[_ ]impact|\bBBQ\b|WinoBias|StereoSet|CrowS-?Pairs|equal_opportunity",
      requires=("training", "model_loading")),
    E("AIS-EV-DATA-FILTER", "Disallowed content removal before training", "1.3.4",
      pattern=r"\bdetoxify\b|\bnsfw\b|toxicity|PhotoDNA|\bcsam\b|dataset[_ ]filter|filter[_ ]dataset|safety[_ ]filter|better_profanity|llama[_ -]?guard|pii[_ ]removal|content[_ ]filter",
      requires=("training",), confidence="low"),
    E("AIS-EV-DATA-WATERMARK", "Dataset watermarking / canaries", "1.1.5",
      pattern=r"dataset[_ ]watermark|data[_ ]watermark|radioactive[_ ]data|dataset[_ ]fingerprint|canary[_ ]records?|data[_ ]canar(?:y|ies)",
      requires=("training",)),
]
